.darma-loader-tw-equalizer { display: inline-flex; align-items: center; justify-content: space-between; width: var(--loader-size, 64px); height: calc(var(--loader-size, 64px) * .6); }
.darma-loader-tw-equalizer span { width: calc(var(--loader-size, 64px) * .12); height: 100%; border-radius: 9999px; background: linear-gradient(to top, var(--loader-color, #d946ef), var(--loader-secondary-color, #6366f1)); animation: darma-loader-tw-equalizer-twEq calc(var(--loader-speed, 1s) * 1.1) ease-in-out infinite; }
.darma-loader-tw-equalizer span:nth-child(2) { animation-delay: calc(var(--loader-speed, 1s) * .12); }
.darma-loader-tw-equalizer span:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * .24); }
.darma-loader-tw-equalizer span:nth-child(4) { animation-delay: calc(var(--loader-speed, 1s) * .36); }
.darma-loader-tw-equalizer span:nth-child(5) { animation-delay: calc(var(--loader-speed, 1s) * .48); }
@keyframes darma-loader-tw-equalizer-twEq { 0%, 100% { transform: scaleY(.25); } 50% { transform: scaleY(1); } }

